function winner(b){
  var L=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
  for(var i=0;i<L.length;i++){ var a=L[i][0],c=L[i][1],d=L[i][2]; if(b[a]&&b[a]===b[c]&&b[a]===b[d]) return b[a]; }
  if(b.every(function(x){return x;})) return 'draw';
  return null;
}
function emptyCells(b){var r=[];for(var i=0;i<9;i++) if(!b[i]) r.push(i); return r;}
function minimax(b, player){
  var w=winner(b);
  if(w==='X') return {score:-10};
  if(w==='O') return {score:10};
  if(w==='draw') return {score:0};
  var moves=[];
  emptyCells(b).forEach(function(i){
    var nb=b.slice(); nb[i]=player;
    var res=minimax(nb, player==='O'?'X':'O');
    moves.push({idx:i, score: res.score});
  });
  var bi=0;
  if(player==='O'){ var best=-Infinity; moves.forEach(function(m){if(m.score>best){best=m.score;bi=m.idx;}}); return {score:best, idx:bi}; }
  else { var worst=Infinity; moves.forEach(function(m){if(m.score<worst){worst=m.score;bi=m.idx;}}); return {score:worst, idx:bi}; }
}
function bestMove(b){ return minimax(b.slice(),'O').idx; }
var EXPORTS={winner:winner,bestMove:bestMove,emptyCells:emptyCells};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TicTacToeForgePure = EXPORTS; }
